{
  "$id": "https://coding-hermes.local/chd32/schemas/run-record.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "allOf": [
    {
      "if": {
        "properties": {
          "state": {
            "enum": [
              "stopped",
              "terminal"
            ]
          }
        }
      },
      "then": {
        "required": [
          "ended_at",
          "stop_proof_ref"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "state": {
            "enum": [
              "unknown",
              "unreachable"
            ]
          }
        }
      },
      "then": {
        "properties": {
          "stop_proof_ref": {
            "type": "null"
          }
        }
      }
    }
  ],
  "properties": {
    "attempt_id": {
      "minLength": 1,
      "type": "string"
    },
    "created_at": {
      "format": "date-time",
      "type": "string"
    },
    "ended_at": {
      "format": "date-time",
      "type": [
        "string",
        "null"
      ]
    },
    "exit_reason": {
      "type": [
        "string",
        "null"
      ]
    },
    "reservation_id": {
      "minLength": 1,
      "type": "string"
    },
    "run_id": {
      "minLength": 1,
      "type": "string"
    },
    "schema_version": {
      "const": 1
    },
    "send_id": {
      "minLength": 1,
      "type": "string"
    },
    "state": {
      "enum": [
        "queued",
        "admitted",
        "running",
        "stopped",
        "terminal",
        "unknown",
        "unreachable"
      ]
    },
    "stop_proof_ref": {
      "type": [
        "string",
        "null"
      ]
    }
  },
  "required": [
    "schema_version",
    "run_id",
    "send_id",
    "attempt_id",
    "state",
    "reservation_id",
    "created_at"
  ],
  "title": "CHD RunRecord v1",
  "type": "object"
}
